// One trailer. Index 0 is the trailer attached to the truck, doubles and triples follow. Everything is 0 for slots without a trailer.
struct Trailer {
    bool connected;  // True while the trailer is connected to the truck.
    bool present;  // True while the game reports a configuration for this trailer slot. Stays true while the trailer is detached.
    char id[64];  // Trailer identifier for code.
    char cargo_accessory_id[64];  // Identifier of the cargo accessory (the load) of the trailer.
    char brand_id[64];  // Brand identifier for code.
    char brand[64];  // Brand name for display.
    char name[64];  // Trailer name for display.
    char chain_type[64];  // Chain type of the trailer combination. Only reported for the first trailer.
    char body_type[64];  // Body type of the trailer. Only reported for the first trailer.
    char license_plate[64];  // License plate text.
    char license_plate_country[64];  // License plate country name for display.
    char license_plate_country_id[64];  // License plate country identifier for code.
    uint8_t _pad0[2];  // Explicit padding, always 0.
    uint32_t wheel_count;  // Number of wheels. Only this many entries of wheels[] are valid.
    Vec3f hook_position;  // Position of the trailer hook in trailer space. Unit: m.
    float cargo_damage;  // Damage of the cargo loaded on this trailer. Unit: [0, 1].
    PlacementD world;  // World position and orientation of the trailer. Unit: m / turns.
    Vec3f local_linear_velocity;  // Linear velocity in trailer space. Unit: m/s.
    Vec3f local_angular_velocity;  // Angular velocity in trailer space. Unit: rotations/s.
    Vec3f local_linear_acceleration;  // Linear acceleration in trailer space. Unit: m/s^2.
    Vec3f local_angular_acceleration;  // Angular acceleration in trailer space. Unit: rotations/s^2.
    float wear_body;  // Wear of the trailer body. Unit: [0, 1].
    float wear_chassis;  // Wear of the trailer chassis. Unit: [0, 1].
    float wear_wheels;  // Average wear of the trailer wheels. Unit: [0, 1].
    Wheel wheels[16];  // Wheels of the trailer.
    uint8_t _pad1[4];  // Explicit padding, always 0.
};

