// The active job. Everything is 0 while no job is active.
struct Job {
    bool present;  // True while a job is active.
    char cargo_id[64];  // Cargo identifier for code.
    char cargo[64];  // Cargo name for display.
    uint8_t _pad0[3];  // Explicit padding, always 0.
    float cargo_mass;  // Total mass of the cargo. Unit: kg.
    float cargo_unit_mass;  // Mass of one cargo unit. Unit: kg.
    uint32_t cargo_unit_count;  // Number of cargo units of the job.
    float cargo_damage;  // Total damage of the cargo. Unit: [0, 1].
    bool is_cargo_loaded;  // True if the cargo is loaded on the trailer. Always true for jobs that do not come from the cargo market.
    bool special_job;  // True for special transport jobs.
    char market[32];  // Where the job comes from: "cargo_market", "quick_job", "freight_market", "external_contracts" or "external_market".
    char source_city_id[64];  // Identifier of the source city for code.
    char source_city[64];  // Name of the source city for display.
    char source_company_id[64];  // Identifier of the source company for code. Empty for special transport jobs.
    char source_company[64];  // Name of the source company for display. Empty for special transport jobs.
    char destination_city_id[64];  // Identifier of the destination city for code.
    char destination_city[64];  // Name of the destination city for display.
    char destination_company_id[64];  // Identifier of the destination company for code. Empty for special transport jobs.
    char destination_company[64];  // Name of the destination company for display. Empty for special transport jobs.
    uint8_t _pad1[2];  // Explicit padding, always 0.
    uint64_t income;  // Expected income without penalties, in the game's currency (ETS2: Euro, ATS: US dollar). Unit: currency.
    uint32_t planned_distance_km;  // Planned distance of the job in simulated kilometers. Does not include ferry distance. Unit: km.
    uint32_t delivery_time_minutes;  // Absolute in-game time at which the delivery window ends. Compare with game.game_time_minutes. Unit: in-game minutes.
    int32_t delivery_time_remaining_minutes;  // delivery_time_minutes minus the current in-game time. Negative once the job is late. Derived by the plugin. Unit: in-game minutes.
    uint32_t started_game_time_minutes;  // In-game time at which the plugin saw the job appear (0 if the game time was not known yet, for example when the job was already active while the plugin loaded). Derived by the plugin. Unit: in-game minutes.
};

