// Last job that was delivered.
struct JobDeliveredEvent {
    uint32_t count;  // How many times the event fired since the plugin loaded. A change means a new event.
    uint32_t game_time_minutes;  // In-game time when the event fired. Unit: in-game minutes.
    int64_t revenue;  // Revenue of the job in the game's currency. Unit: currency.
    int32_t earned_xp;  // XP the player received.
    float cargo_damage;  // Total cargo damage at delivery. Unit: [0, 1].
    float distance_km;  // Real distance driven on the job. Unit: km.
    uint32_t delivery_time_minutes;  // Total time spent on the job. Unit: in-game minutes.
    bool autopark_used;  // True if auto parking was used.
    bool autoload_used;  // True if auto loading was used (always true for non cargo market jobs).
    uint8_t _pad0[6];  // Explicit padding, always 0.
};

