// Gameplay events. Each entry keeps the payload of the last occurrence, detect a new occurrence by a change of its count.
struct Events {
    JobDeliveredEvent job_delivered;  // Last delivered job.
    JobCancelledEvent job_cancelled;  // Last cancelled job.
    FinedEvent fined;  // Last fine.
    TollgateEvent tollgate;  // Last paid tollgate.
    FerryEvent ferry;  // Last used ferry.
    TrainEvent train;  // Last used train.
};

