// Everything the plugin publishes. One consistent copy exists per game frame.
struct TelemetryData {
    Game game;  // State of the game and its clocks.
    Truck truck;  // The truck the player drives.
    Trailer trailers[10];  // Trailers, index 0 is the first trailer.
    Job job;  // The active job.
    Events events;  // Gameplay events.
    Substances substances;  // Surface types.
    uint8_t _pad0[4];  // Explicit padding, always 0.
};

static_assert(sizeof(TelemetryData) == 21808, "TelemetryData layout");
static_assert(offsetof(TelemetryData, game) == 0, "TelemetryData layout");
static_assert(offsetof(TelemetryData, truck) == 72, "TelemetryData layout");
